select a.product_code,a.product_type,b.open_price,c.close_price,a.high_price,a.low_price,a.average_price,a.volumes,a.amount,start_time,start_time specific_time from (select product_code, product_type, min(id) first_id, max(id) last_id, max(high_price) high_price, min(low_price) low_price, avg(average_price) average_price, sum(volumes) volumes, sum(amount) amount, start_time, end_time from (select product_code, product_type, id, high_price, low_price, average_price, volumes, amount, FROM_UNIXTIME(UNIX_TIMESTAMP(specific_time) - UNIX_TIMESTAMP(specific_time) % #{params.timeInterval}) start_time, FROM_UNIXTIME(UNIX_TIMESTAMP(specific_time) - UNIX_TIMESTAMP(specific_time) % #{params.timeInterval} + #{params.timeInterval}) end_time from self_sell_product_real_time where product_code = #{productCode} and product_type = #{productType}
and date_format(specific_time,'%Y-%m-%d %H:%i:%s') <= date_format(#{params.KlineTime},'%Y-%m-%d %H:%i:%s')
order by specific_time desc limit #{params.limit} ) as a GROUP BY start_time, end_time) as a INNER JOIN self_sell_product_real_time b on a.first_id = b.id INNER JOIN self_sell_product_real_time c on a.last_id = c.id

select sum(volumes) volumes,max(high_price) highPrice,min(low_price) lowPrice,sum(amount) amount,product_code productCode, (select open_price from self_sell_product_real_time where product_code = #{productCode} and product_type = #{productType}
and date_format(specific_time,'%y%m%d') >= date_format(#{date},'%y%m%d')
and date_format(specific_time,'%y%m%d') = date_format(#{date},'%y%m%d') and date_format(specific_time,'%Y-%m-%d %H:%i:%s') <= date_format(#{date},'%Y-%m-%d %H:%i:%s') order by specific_time limit 1) openPrice, (select close_price from self_sell_product_real_time where product_code = #{productCode} and product_type = #{productType}
and date_format(specific_time,'%y%m%d') <= date_format(#{date},'%y%m%d')
and date_format(specific_time,'%y%m%d') = date_format(#{date},'%y%m%d') and date_format(specific_time,'%Y-%m-%d %H:%i:%s') <= date_format(#{date},'%Y-%m-%d %H:%i:%s') order by specific_time desc limit 1) closePrice, (select close_price from self_sell_product_real_time where product_code = #{productCode} and product_type = #{productType} and date_format(specific_time,'%y%m%d') < date_format(#{date},'%y%m%d') order by specific_time desc limit 1) closePricePrevDay from self_sell_product_real_time where product_code = #{productCode} and product_type = #{productType}
and date_format(specific_time,'%y%m%d') >= date_format(#{date},'%y%m%d')
